// 任务类型分析
export function analyzeTaskType(input) {
  if (!input || typeof input !== 'string') {
    return { type: 'unknown', confidence: 0 };
  }
  
  const text = input.toLowerCase();
  const scores = {};
  
  for (const [type, keywords] of Object.entries(TASK_TYPE_KEYWORDS)) {
    let matchCount = 0;
    for (const keyword of keywords) {
      if (text.includes(keyword.toLowerCase())) {
        matchCount++;
      }
    }
    if (matchCount > 0) {
      scores[type] = matchCount / keywords.length;
    }
  }
  
  // 找出最高匹配分
  let bestType = 'text'; // 默认
  let bestScore = 0;
  
  for (const [type, score] of Object.entries(scores)) {
    if (score > bestScore) {
      bestScore = score;
      bestType = type;
    }
  }
  
  return {
    type: bestType,
    confidence: Math.min(bestScore * 3, 1), // 标准化到 0-1
    allScores: scores
  };
}

// 推荐工具
export function recommendTools(input) {
  const analysis = analyzeTaskType(input);
  const recommendations = [];
  
  // 获取推荐映射
  const recs = TASK_TOOL_RECOMMENDATIONS[analysis.type] || [];
  
  for (const rec of recs) {
    const tool = toolRegistry.get(rec.id);
    if (tool) {
      recommendations.push({
        tool,
        score: rec.score * analysis.confidence,
        reason: rec.reason,
        matchedType: analysis.type
      });
    }
  }
  
  // 如果没有匹配，添加一些通用工具
  if (recommendations.length === 0) {
    const generalTools = [
      { id: 'word-count', reason: '快速统计文本长度' },
      { id: 'quality-check', reason: '检查内容质量' }
    ];
    for (const g of generalTools) {
      const tool = toolRegistry.get(g.id);
      if (tool) {
        recommendations.push({
          tool,
          score: 50,
          reason: g.reason,
          matchedType: 'general'
        });
      }
    }
  }
  
  // 按分数排序
  recommendations.sort((a, b) => b.score - a.score);
  
  return {
    analysis,
    recommendations: recommendations.slice(0, 5), // 最多返回5个
    timestamp: Date.now()
  };
}

